# Four-eyes control in the database, on top of guardrail G5 in the master:
# the CHECK on cases stops maker = checker; these triggers also require the
# right roles, and that a final rating is approved by the case's checker.
FOUR_EYES_SQL = """
CREATE FUNCTION kyc_case_roles() RETURNS trigger AS $$
BEGIN
    IF (SELECT role FROM users WHERE id = NEW.maker_id) <> 'maker' THEN
        RAISE EXCEPTION 'four-eyes: case % maker (user %) must have role maker', NEW.case_ref, NEW.maker_id;
    END IF;
    IF (SELECT role FROM users WHERE id = NEW.checker_id) <> 'checker' THEN
        RAISE EXCEPTION 'four-eyes: case % checker (user %) must have role checker', NEW.case_ref, NEW.checker_id;
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;

CREATE TRIGGER trg_cases_four_eyes BEFORE INSERT OR UPDATE OF maker_id, checker_id ON cases
    FOR EACH ROW EXECUTE FUNCTION kyc_case_roles();

CREATE FUNCTION kyc_final_rating_approver() RETURNS trigger AS $$
DECLARE c cases%ROWTYPE;
BEGIN
    IF NEW.is_final THEN
        SELECT * INTO c FROM cases WHERE id = NEW.case_id;
        IF NEW.approved_by = c.maker_id THEN
            RAISE EXCEPTION 'four-eyes: the maker of case % cannot approve its rating', c.case_ref;
        END IF;
        IF NEW.approved_by <> c.checker_id THEN
            RAISE EXCEPTION 'four-eyes: only the assigned checker can approve case %', c.case_ref;
        END IF;
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;

CREATE TRIGGER trg_ratings_four_eyes BEFORE INSERT OR UPDATE ON ratings
    FOR EACH ROW EXECUTE FUNCTION kyc_final_rating_approver();
"""


